create table public.supplier_payments (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,supplier_id bigint not null references public.parties(id) on delete cascade,payment_number text not null,payment_date date not null,payment_method text not null,reference text,bank_reference text,amount numeric(14,2) not null check(amount>=0),status text not null default 'pending',notes text,approved_at timestamptz,file_path text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(business_id,payment_number));
create table public.payment_schedules (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,supplier_id bigint not null references public.parties(id) on delete cascade,scheduled_date date not null,amount numeric(14,2) not null check(amount>=0),status text not null default 'pending',paid_date date,payment_method text,notes text,reminders_sent boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.aging_reports (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,supplier_id bigint not null references public.parties(id) on delete cascade,report_date date not null,period_30 numeric(14,2) not null default 0,period_60 numeric(14,2) not null default 0,period_90 numeric(14,2) not null default 0,period_90_plus numeric(14,2) not null default 0,total numeric(14,2) not null default 0,generated_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin for t in select unnest(array['supplier_payments','payment_schedules','aging_reports']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on table public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select private.current_business_id())) with check (business_id=(select private.current_business_id()))',t||'_tenant_policy',t); end loop; end $$;
create index supplier_payments_business_date_idx on public.supplier_payments(business_id,payment_date);
create index payment_schedules_business_date_idx on public.payment_schedules(business_id,scheduled_date);
create index aging_reports_business_date_idx on public.aging_reports(business_id,report_date);